"use client";
import {useRef,useState} from "react";
import {useRouter} from "next/navigation";
import {supplierComparisonAction} from "@/lib/actions/supplier-comparisons";
import {type SupplierComparison} from "@/lib/workflow/supplier-comparisons";
import {Button} from "@/components/ui/button";
import {formatCurrency} from "@/lib/utils/format";

export function NewSupplierComparison(){
  const router=useRouter(),requestId=useRef(crypto.randomUUID());
  const [form,setForm]=useState({title:"",specification:"",unit:"kg",quantity:"",required_by:""}),[busy,setBusy]=useState(false),[error,setError]=useState("");
  function change(key:keyof typeof form,value:string){setForm(current=>({...current,[key]:value}));requestId.current=crypto.randomUUID();}
  async function submit(event:React.FormEvent){event.preventDefault();if(busy)return;setBusy(true);setError("");try{const result=await supplierComparisonAction({command:"request.create",id:requestId.current,...form,quantity:Number(form.quantity),required_by:form.required_by||null});if(!result.success)setError(result.error);else if(result.kind==="saved")router.push(`/vendors/comparisons/${result.data.id}`);}finally{setBusy(false);}}
  return <form onSubmit={submit} className="max-w-3xl space-y-4 rounded-2xl border bg-white p-4 sm:p-6"><label className="block">Purchase requirement<input required className="form-input" maxLength={160} value={form.title} onChange={e=>change("title",e.target.value)}/></label><label className="block">Exact specification<textarea required className="form-input min-h-28" maxLength={2000} value={form.specification} onChange={e=>change("specification",e.target.value)} placeholder="Alloy, temper, dimensions, finish, applicable standard and required evidence"/></label><div className="grid gap-4 sm:grid-cols-3"><label>Required quantity<input required className="form-input" type="number" min="0.001" step="0.001" value={form.quantity} onChange={e=>change("quantity",e.target.value)}/></label><label>Base unit<select aria-label="Base unit" className="form-input" value={form.unit} onChange={e=>change("unit",e.target.value)}>{["kg","m","piece"].map(unit=><option key={unit}>{unit}</option>)}</select></label><label>Required by<input className="form-input" type="date" value={form.required_by} onChange={e=>change("required_by",e.target.value)}/></label></div><p className="text-sm text-slate-600">This comparison records the required basis. It creates no purchase order or stock entry. Changed specifications should start a separate comparison.</p><Button disabled={busy} type="submit">{busy?"Saving...":"Create purchase comparison"}</Button>{error?<p role="alert" className="text-red-700">{error}</p>:null}</form>;
}

export function NewSupplierOffer({requestId}:{requestId:string}){
  const router=useRouter(),identity=useRef(crypto.randomUUID());
  const [vendors,setVendors]=useState<{id:string;vendor_name:string}[]>([]),[vendorPage,setVendorPage]=useState(1),[vendorSearch,setVendorSearch]=useState(""),[busy,setBusy]=useState(false),[error,setError]=useState("");
  const [form,setForm]=useState({vendor_id:"",source_reference:"",offered_quantity:"",unit:"kg",unit_rate:"",freight_mode:"unknown",freight_amount:"",gst_percent:"18",freight_gst_percent:"18",delivery_date:"",valid_until:"",payment_terms:"",specification_matches:false,exclusions:""});
  function change(key:keyof typeof form,value:string|boolean){setForm(current=>({...current,[key]:value}));identity.current=crypto.randomUUID();}
  async function findVendors(page=1){setBusy(true);setError("");try{const result=await supplierComparisonAction({command:"vendors.list",page,search:vendorSearch});if(!result.success)setError(result.error);else if(result.kind==="vendors"){setVendors(result.data.items);setVendorPage(page);}}finally{setBusy(false);}}
  async function submit(event:React.FormEvent){event.preventDefault();if(busy)return;setBusy(true);setError("");try{const result=await supplierComparisonAction({command:"offer.create",...form,id:identity.current,request_id:requestId,document_id:null,offered_quantity:Number(form.offered_quantity),unit_rate:Number(form.unit_rate),freight_amount:form.freight_amount===""?null:Number(form.freight_amount),gst_percent:Number(form.gst_percent),freight_gst_percent:Number(form.freight_gst_percent),delivery_date:form.delivery_date||null,valid_until:form.valid_until||null});if(!result.success)setError(result.error);else if(result.kind==="saved")router.push(`/vendors/comparisons/${requestId}`);}finally{setBusy(false);}}
  return <form className="max-w-4xl space-y-4 rounded-2xl border bg-white p-4 sm:p-6" onSubmit={submit}><div className="flex flex-wrap gap-2"><input aria-label="Find supplier" className="form-input flex-1" value={vendorSearch} onChange={e=>setVendorSearch(e.target.value)} placeholder="Search active company suppliers"/><Button type="button" variant="secondary" disabled={busy} onClick={()=>findVendors()}>Find suppliers</Button></div><label className="block">Supplier<select aria-label="Supplier" required className="form-input" value={form.vendor_id} onChange={e=>change("vendor_id",e.target.value)}><option value="">Choose supplier</option>{form.vendor_id&&!vendors.some(v=>v.id===form.vendor_id)?<option value={form.vendor_id}>Selected supplier</option>:null}{vendors.map(v=><option key={v.id} value={v.id}>{v.vendor_name}</option>)}</select></label><div className="flex gap-2"><Button type="button" variant="secondary" disabled={busy||vendorPage===1} onClick={()=>findVendors(vendorPage-1)}>Previous suppliers</Button><Button type="button" variant="secondary" disabled={busy||vendors.length<10} onClick={()=>findVendors(vendorPage+1)}>More suppliers</Button></div>
    <label className="block">Supplier quotation / source document reference<input required className="form-input" maxLength={200} value={form.source_reference} onChange={e=>change("source_reference",e.target.value)}/></label>
    <div className="grid gap-4 sm:grid-cols-3">
      {([['offered_quantity','Offered quantity'],['unit_rate','Rate INR per offered unit'],['gst_percent','Goods GST %']] as const).map(([key,label])=><label key={key}>{label}<input required type="number" min="0" step="any" className="form-input" value={form[key]} onChange={e=>change(key,e.target.value)}/></label>)}
      <label>Offered unit<select aria-label="Offered unit" className="form-input" value={form.unit} onChange={e=>change("unit",e.target.value)}>{["kg","tonne","g","m","mm","piece","dozen"].map(unit=><option key={unit}>{unit}</option>)}</select></label>
      <label>Freight basis<select aria-label="Freight basis" className="form-input" value={form.freight_mode} onChange={e=>change("freight_mode",e.target.value)}><option value="unknown">Not confirmed</option><option value="included">Included in quoted rate</option><option value="excluded">Additional freight</option></select></label>
      <label>Additional freight INR<input type="number" min="0" step="0.01" className="form-input" value={form.freight_amount} onChange={e=>change("freight_amount",e.target.value)} placeholder="Unknown if blank"/></label>
      <label>Freight GST %<input required type="number" min="0" max="100" className="form-input" value={form.freight_gst_percent} onChange={e=>change("freight_gst_percent",e.target.value)}/></label>
      <label>Delivery date<input type="date" className="form-input" value={form.delivery_date} onChange={e=>change("delivery_date",e.target.value)}/></label>
      <label>Valid until<input type="date" className="form-input" value={form.valid_until} onChange={e=>change("valid_until",e.target.value)}/></label>
    </div>
    <label className="block">Payment terms<input required className="form-input" maxLength={500} value={form.payment_terms} onChange={e=>change("payment_terms",e.target.value)}/></label><label className="block">Exclusions and unmatched conditions<textarea className="form-input" maxLength={1000} value={form.exclusions} onChange={e=>change("exclusions",e.target.value)} placeholder="Record every exclusion, specification deviation or commercial condition"/></label><label className="flex items-start gap-2 text-sm"><input type="checkbox" checked={form.specification_matches} onChange={e=>change("specification_matches",e.target.checked)}/>I checked the supplier source against the complete requested specification.</label><p className="text-sm text-slate-600">Missing freight, validity or delivery information remains visible as requiring review. Each saved offer is retained; record a new offer when the supplier changes it.</p><Button type="submit" disabled={busy}>{busy?"Recording...":"Record supplier offer"}</Button>{error?<p role="alert" className="text-red-700">{error}</p>:null}
  </form>;
}

export function SupplierComparisonPanel({initial}:{initial:SupplierComparison}){
  const [view,setView]=useState(initial),[reason,setReason]=useState(""),[error,setError]=useState(""),[busy,setBusy]=useState(false);const request=useRef({id:crypto.randomUUID(),offer:"",reason:""});
  async function load(page=view.page){setBusy(true);setError("");try{const result=await supplierComparisonAction({command:"request.load",request_id:view.request.id,page});if(!result.success)setError(result.error);else if(result.kind==="comparison")setView(result.data);}finally{setBusy(false);}}
  async function recommend(offerId:string){if(request.current.offer!==offerId||request.current.reason!==reason)request.current={id:crypto.randomUUID(),offer:offerId,reason};setBusy(true);setError("");try{const result=await supplierComparisonAction({command:"recommendation.record",request_id:view.request.id,offer_id:offerId,id:request.current.id,reason});if(!result.success){setError(result.error);return;}await load();}finally{setBusy(false);}}
  return <div className="space-y-5"><section className="space-y-2 rounded-2xl border bg-white p-4"><h2 className="font-bold">{view.request.title}: {view.request.quantity} {view.request.unit}</h2><p className="whitespace-pre-wrap text-sm">{view.request.specification}</p><p className="text-sm">Required by {view.request.required_by||"Not captured"}.</p><p className="text-xs text-slate-600">{view.basis}</p><a className="inline-block font-bold underline" href={`/vendors/comparisons/${view.request.id}/offers/new`}>Record another supplier offer</a></section>
    <section className="space-y-3 rounded-2xl border bg-white p-4"><h2 className="font-bold">Supplier offers</h2><p className="text-sm text-slate-600">Price eligibility checks the recorded basis. Compare payment and delivery terms explicitly before recommending a supplier. Previous offers remain visible.</p><div className="overflow-x-auto"><table className="industrial-table min-w-[850px]"><thead><tr><th>Supplier / source</th><th>Normalized rate</th><th>Freight</th><th>Landed before tax / cash</th><th>Delivery / payment</th><th>Review</th></tr></thead><tbody>{view.offers.map(offer=><tr key={offer.id}><td>{offer.vendor_name}<p className="text-xs">{offer.source_reference}</p><p className="text-xs">{offer.offered_quantity} {offer.offered_unit}</p></td><td>{formatCurrency(offer.normalized_rate)} / {offer.normalized_unit}</td><td>{offer.freight_mode}{offer.freight_amount!==null?<p>{formatCurrency(offer.freight_amount)}</p>:null}</td><td>{offer.landed_before_tax===null?"Requires review":formatCurrency(offer.landed_before_tax)}<p>{offer.cash_total===null?"Tax basis unavailable":formatCurrency(offer.cash_total)}</p></td><td>{offer.delivery_date||"Not captured"}<p>{offer.payment_terms}</p><p>Valid until {offer.valid_until||"Not captured"}</p></td><td>{offer.price_basis_matches?<><p className="text-emerald-800">Recorded price basis matches</p><Button disabled={busy||reason.trim().length<5} onClick={()=>recommend(offer.id)}>Recommend supplier</Button></>:<ul className="list-disc pl-4 text-amber-900">{offer.reasons.map(item=><li key={item}>{item}</li>)}</ul>}{offer.exclusions?<p>{offer.exclusions}</p>:null}</td></tr>)}</tbody></table></div>{!view.offers.length?<p className="text-sm">No supplier offers recorded on this page.</p>:null}<label className="block text-sm font-bold">Recommendation rationale<input className="form-input" value={reason} maxLength={1000} onChange={e=>setReason(e.target.value)} placeholder="Explain specification, landed cost, delivery and payment tradeoffs"/></label><div className="flex flex-wrap items-center gap-3"><Button variant="secondary" disabled={busy||view.page===1} onClick={()=>load(view.page-1)}>Previous offers</Button><span>Page {view.page}</span><Button variant="secondary" disabled={busy||view.offers.length<10} onClick={()=>load(view.page+1)}>More offers</Button><Button variant="secondary" disabled={busy} onClick={()=>load()}>Refresh comparison</Button></div></section>
    <section className="space-y-2 rounded-2xl border bg-white p-4"><h2 className="font-bold">Recorded recommendations</h2>{view.recommendations.length?view.recommendations.map(item=><p className="text-sm" key={item.id}>{item.reason}<span className="block text-xs text-slate-600">Recorded {item.created_at} · retained offer {item.offer_id}</span></p>):<p className="text-sm">No recommendation recorded.</p>}<p className="text-xs text-slate-600">A recommendation does not issue a purchase order or post a financial transaction.</p></section>{error?<p role="alert" className="text-red-700">{error}</p>:null}
  </div>;
}
